import sizes from "./image-sizes.json";

export type ImageSize = { width: number; height: number };

/**
 * Intrinsic pixel dimensions of everything in public/, generated by
 * `scripts/measure-images.ps1`. The masonry layout needs each photo's
 * aspect ratio on the server, before anything has loaded — re-run the
 * script whenever you add or replace photography.
 */
const SIZES = sizes as Record<string, ImageSize>;

/** Falls back to a 4:5 portrait so a missing entry cannot break the layout. */
export function imageSize(src?: string): ImageSize {
  return (src ? SIZES[src] : undefined) ?? { width: 800, height: 1000 };
}
